PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(
 id INTEGER PRIMARY KEY, handle TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL,
 password TEXT, bio TEXT NOT NULL DEFAULT '', avatar TEXT NOT NULL DEFAULT '', website TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tags(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, icon TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS posts(
 id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL CHECK(kind IN ('article','pulse')),
 title TEXT NOT NULL DEFAULT '', body TEXT NOT NULL, image TEXT NOT NULL DEFAULT '', featured INTEGER NOT NULL DEFAULT 0 CHECK(featured IN (0,1)),
 views INTEGER NOT NULL DEFAULT 0 CHECK(views>=0), series TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS post_tags(post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,tag_id INTEGER REFERENCES tags(id),PRIMARY KEY(post_id,tag_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY, post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,user_id INTEGER NOT NULL REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS likes(user_id INTEGER REFERENCES users(id),post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,PRIMARY KEY(user_id,post_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS bookmarks(user_id INTEGER REFERENCES users(id),post_id INTEGER REFERENCES posts(id) ON DELETE CASCADE,PRIMARY KEY(user_id,post_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS follows(user_id INTEGER REFERENCES users(id),target_id INTEGER REFERENCES users(id),CHECK(user_id<>target_id),PRIMARY KEY(user_id,target_id)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS checkins(user_id INTEGER REFERENCES users(id),day TEXT,PRIMARY KEY(user_id,day)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,level TEXT NOT NULL,author TEXT NOT NULL,summary TEXT NOT NULL,description TEXT NOT NULL,color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lessons(id INTEGER PRIMARY KEY,course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE CASCADE,position INTEGER NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,UNIQUE(course_id,position));
CREATE INDEX IF NOT EXISTS posts_feed ON posts(kind,created_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS posts_author ON posts(user_id,kind);
CREATE INDEX IF NOT EXISTS posts_featured ON posts(kind,featured);
CREATE INDEX IF NOT EXISTS comments_post ON comments(post_id,id);
CREATE INDEX IF NOT EXISTS post_tags_tag ON post_tags(tag_id,post_id);
CREATE INDEX IF NOT EXISTS likes_post ON likes(post_id);
CREATE INDEX IF NOT EXISTS follows_target ON follows(target_id);
